package ir.ghiyas.alimaa.core.utils

import kotlinx.browser.document
import kotlinx.browser.window
import org.w3c.dom.HTMLAnchorElement
import org.w3c.dom.HTMLInputElement
import org.w3c.dom.url.URL
import org.w3c.files.Blob
import org.w3c.files.BlobPropertyBag
import org.w3c.files.FileReader
import org.w3c.files.get
import kotlin.js.json

object WebFileIO {
    
    // ۱. روش مستقیم (مخصوص کروم و PWA دسکتاپ)
    fun exportViaDirectDownload(filename: String, content: String) {
        val blob = Blob(arrayOf(content), BlobPropertyBag(type = "application/json"))
        val url = URL.createObjectURL(blob)
        val anchor = document.createElement("a") as HTMLAnchorElement
        anchor.href = url
        anchor.download = filename
        document.body?.appendChild(anchor)
        anchor.click()
        document.body?.removeChild(anchor)
        URL.revokeObjectURL(url)
    }

    // ۲. روش اشتراک‌گذاری (مخصوص فایرفاکس و موبایل)
    fun exportViaWebShare(filename: String, content: String, onFailed: () -> Unit) {
        val blob = Blob(arrayOf(content), BlobPropertyBag(type = "application/json"))
        val nav = window.navigator.asDynamic()
        
        if (nav.canShare != undefined) {
            try {
                val file = js("new File([blob], filename, {type: 'application/json'})")
                val shareData = json(
                    "files" to arrayOf(file),
                    "title" to "پشتیبان قیاس",
                    "text" to "فایل پشتیبان اطلاعات قیاس"
                )
                
                if (nav.canShare(shareData).unsafeCast<Boolean>()) {
                    nav.share(shareData).asDynamic()
                        .then { console.log("اشتراک‌گذاری موفق بود") }
                        .catch { e: Throwable ->
                            console.error("اشتراک‌گذاری لغو شد یا در این مرورگر پشتیبانی نمی‌شود")
                            onFailed()
                        }
                    return
                } else {
                    onFailed()
                }
            } catch (e: Exception) {
                console.error("خطا در تنظیمات اشتراک‌گذاری", e)
                onFailed()
            }
        } else {
            onFailed()
        }
    }

    // ۳. بازیابی از طریق فایل فیزیکی (آفلاین)
    fun importJsonFile(onFileSelected: () -> Unit, onResult: (String?) -> Unit) {
        val input = document.createElement("input") as HTMLInputElement
        input.type = "file"
        input.accept = ".json"
        
        var fileIsSelected = false
        
        input.onchange = {
            val file = input.files?.get(0)
            if (file != null) {
                fileIsSelected = true
                onFileSelected()
                val reader = FileReader()
                FileReader::class.js // جلوگیری از حذف شدن توسط کامپایلر
                reader.onload = { _ ->
                    onResult(reader.result as? String)
                }
                reader.onerror = {
                    console.error("خطا در خواندن فایل")
                    onResult(null)
                }
                reader.readAsText(file)
            }
            null
        }
        
        window.addEventListener("focus", {
            window.setTimeout({
                val files = input.files
                val hasFiles = files != null && files.length > 0
                if (!fileIsSelected && !hasFiles) {
                    onResult("CANCELED")
                }
            }, 300)
        }, json("once" to true))
        
        input.click()
    }

    // ۴. بازیابی از طریق لینک (آنلاین / ابری)
    fun importFromUrl(url: String, onResult: (String?, String?) -> Unit) {
        // استفاده از asDynamic برای رهایی از مشکلات Type Inference کامپایلر Kotlin/JS روی Promise ها
        window.fetch(url).asDynamic()
            .then { response ->
                if (response.ok) {
                    return@then response.text()
                } else {
                    throw Exception("HTTP_ERROR")
                }
            }
            .then { text ->
                // بررسی می‌کنیم که آیا محتوای دریافتی واقعا JSON است یا یک صفحه HTML آپلودر
                val textStr = text as String
                if (textStr.trim().startsWith("{") || textStr.trim().startsWith("[")) {
                    onResult(textStr, null)
                } else {
                    onResult(null, "این لینک حاوی یک صفحه اینترنتی است نه فایل پشتیبان. لطفاً لینک را در مرورگر باز کنید و لینک مستقیم دانلود (Direct Download Link) را اینجا قرار دهید.")
                }
            }
            .catch { e: Throwable ->
                onResult(null, "ارتباط با سرور برقرار نشد یا لینک نامعتبر است (خطای CORS). لطفاً از لینک مستقیم معتبر استفاده کنید.")
            }
    }
}
